package com.pwaquatics.shop.media.infrastructure;

import com.pwaquatics.shop.common.config.AppProperties;
import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.file.DirectoryStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.util.Map;
import java.util.regex.Pattern;
import org.springframework.stereotype.Component;

/** Keeps renditions in {@code app.media.local-path}, one directory per image. */
@Component
class LocalMediaStorage implements MediaStorage {

    /** Keys are generated by the application; anything else is refused (no path tricks). */
    private static final Pattern KEY = Pattern.compile("[a-z]+(/[0-9a-f-]{36}){2}");
    private static final Pattern FILE = Pattern.compile("[0-9]{2,5}\\.webp");

    private final Path root;

    LocalMediaStorage(AppProperties properties) {
        this.root = Path.of(properties.media().localPath()).toAbsolutePath().normalize();
    }

    @Override
    public void store(String storageKey, Map<String, byte[]> renditions) {
        Path directory = directoryOf(storageKey);
        try {
            Files.createDirectories(directory);
            for (Map.Entry<String, byte[]> file : renditions.entrySet()) {
                if (!FILE.matcher(file.getKey()).matches()) {
                    throw new IllegalArgumentException("Unexpected rendition name");
                }
                // Write to a temporary file first, so a half-written image is never served.
                Path temporary = Files.createTempFile(directory, ".upload-", ".tmp");
                Files.write(temporary, file.getValue());
                Files.move(temporary, directory.resolve(file.getKey()), StandardCopyOption.ATOMIC_MOVE,
                        StandardCopyOption.REPLACE_EXISTING);
            }
        } catch (IOException e) {
            delete(storageKey);
            throw new UncheckedIOException("Could not store image", e);
        }
    }

    @Override
    public void delete(String storageKey) {
        Path directory = directoryOf(storageKey);
        if (!Files.isDirectory(directory)) {
            return;
        }
        try (DirectoryStream<Path> files = Files.newDirectoryStream(directory)) {
            for (Path file : files) {
                Files.deleteIfExists(file);
            }
            Files.deleteIfExists(directory);
        } catch (IOException e) {
            throw new UncheckedIOException("Could not delete image", e);
        }
    }

    private Path directoryOf(String storageKey) {
        if (storageKey == null || !KEY.matcher(storageKey).matches()) {
            throw new IllegalArgumentException("Invalid storage key");
        }
        Path directory = root.resolve(storageKey).normalize();
        if (!directory.startsWith(root)) {
            throw new IllegalArgumentException("Invalid storage key");
        }
        return directory;
    }
}
